   """Issue #2257: the Stinkyscape scripts' headers stop calling the set held."""
   import os, re, sys

   d = sys.argv[1]
   SEP = r'(?: |\n//! ?)'
   HELD_SET = re.compile(r'the(' + SEP + r')held(' + SEP + r')Stinkyscape(' + SEP + r')set(' + SEP + r')\(R1420\)')
   HELD_CLAUSE = re.compile(r';' + SEP + r'held' + SEP + r'\(R1420\)')


   def set_claim(m):
       keep = m.group(2) if m.group(1) == ' ' else m.group(1)
       return 'the' + keep + 'Stinkyscape' + m.group(3) + 'set' + m.group(4) + '(R1857000)'


   for name in sorted(os.listdir(d)):
       if not name.endswith('.rs'):
           continue
       path = os.path.join(d, name)
       lines = open(path, encoding='utf-8').read().split('\n')
       n = 0
       while n < len(lines) and lines[n].startswith('//!'):
           n += 1
       head = '\n'.join(lines[:n])
       new = HELD_CLAUSE.sub('', HELD_SET.sub(set_claim, head))
       if new != head:
           open(path, 'w', encoding='utf-8').write('\n'.join([new] + lines[n:]))
