   fn previews_of_shipped_sets_only(text: &str) -> Vec<usize> {
       const CALL: &str = "preview_sets(&[";
       let shipped: Vec<String> = SHIPPED_SETS.iter().map(|set| format!("{set:?}")).collect();
       let mut lines = Vec::new();
       let mut from = 0;
