               .map(|set| set.trim().rsplit("::").next().unwrap_or(""))
               .filter(|name| !name.is_empty())
               .all(|name| shipped.iter().any(|set| set == name));
           if shipped_only {
               lines.push(text[..start].matches('\n').count() + 1);
           }
       }
       lines
   }

